fn build(a: Allocator, parent: *El, n: N, id: []const u8, kind: []const u8) Allocator.Error!void {
    const e = try parent.insert(n.tag);
    for (n.attrs) |at| {
        if (std.mem.eql(u8, at[0], "id")) {
            try e.setAttr("id", try std.fmt.allocPrint(a, "{s}_{s}{s}", .{ id, kind, at[1] }));
        } else if (std.mem.indexOfScalar(u8, at[1], 2) != null) {
            const sz = std.mem.replacementSize(u8, at[1], "\x02", kind);
            const buf = try a.alloc(u8, sz);
            _ = std.mem.replace(u8, at[1], "\x02", kind, buf);
            try e.setAttr(at[0], buf);
        } else try e.setAttr(at[0], at[1]);
    }
    for (n.kids) |k| try build(a, e, k, id, kind);
}

pub fn insertMarkers(a: Allocator, elem: *El, names: []const []const u8, kind: []const u8, id: []const u8) Allocator.Error!void {
    for (names) |name| {
        for (defs) |d| if (std.mem.eql(u8, d.name, name)) {
            for (d.nodes) |n| try build(a, elem, n, id, kind);
            break;
        };
    }
}

test "point marker ids carry the diagram prefix" {
    var arena = std.heap.ArenaAllocator.init(std.testing.allocator);
    defer arena.deinit();
    const root = try El.create(arena.allocator(), "g");
    try insertMarkers(arena.allocator(), root, &.{ "point", "circle", "cross" }, "flowchart-v2", "my-svg");
    try std.testing.expectEqual(@as(usize, 12), root.kids.items.len);
    try std.testing.expectEqualStrings("my-svg_flowchart-v2-pointEnd", root.kids.items[0].getAttr("id").?);
    try std.testing.expectEqualStrings("marker flowchart-v2", root.kids.items[0].getAttr("class").?);
}
